/*
 * A330138  List of pairs [j,k] ordered by increasing j and k according to the
 *          procedure described in the Comments.
 * https://oeis.org/A330138
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   not stated
 * Range:     u8 n <= 63, u16 n <= 63, u32 n <= 63, u64 n <= 63, u128 n <= 63,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computes the nth term of OEIS A330138.
 * The sequence lists the sides (a,b,c) of all right‑angled triangles
 * generated by the parametrisation
 *   p = 2*j^2       = c - a
 *   q = (2*k-1)^2   = c - b
 *   r = 2*j*(2*k-1) = a + b - c
 * for integers j,k ≥ 1, ordered by (j+k) ascending and, for equal
 * sums, by j ascending.  Each triangle contributes its three sides
 * (a,b,c) in that order.
 *
 * a(n) is the n‑th number in this concatenated list.
 *
 * The implementation evaluates the j,k pair for any n in O(1) time
 * using integer arithmetic only.
 */

#include <stdint.h>
#include <stddef.h>

/* Integer square root of an unsigned 64‑bit integer.
   Returns floor(sqrt(x)).  Works for all x that fit in 64 bits. */
static inline idx_t isqrt_u64(idx_t x)
{
    idx_t r = 0;
    /* Set bit to the highest power of four <= x. */
    idx_t bit = (idx_t)1ULL << 62;
    while (bit > x) bit >>= 2;
    while (bit) {
        if (x >= r + bit) {
            x -= r + bit;
            r = (r >> 1) + bit;
        } else {
            r >>= 1;
        }
        bit >>= 2;
    }
    return r;
}

seq_t a(idx_t n)
{
    /* 1. Find the triangle number t (1‑based) that contains the nth term.
       Each triangle contributes 3 terms.  Hence t = ceil(n/3).        */
    idx_t t = (n + 2) / 3;                    /* 0‑based division rounds down */

    /* 2. Find the minimal sum S = j + k such that the total number of
       triangles up to S is at least t.  The total up to S is T(S) =
       (S-1)*S/2.                                                 */
    /* Compute floor sqrt of disc = 1 + 8*t.  For t within uint64 range
       8*t + 1 also fits in uint64.                                 */
    idx_t disc = 1 + (idx_t)8 * t;
    idx_t sqrt_disc = isqrt_u64(disc);
    idx_t S = (1 + sqrt_disc) / 2;
    /* Adjust S upward if necessary. */
    if ( ((unsigned __int128)S * (S - 1)) / 2 < t ) S++;

    /* 3. Determine the offset of this triangle within its (S‑1) block. */
    idx_t prev_triangles = ((unsigned __int128)(S - 1) * (S - 2)) / 2;
    idx_t offset_in_group = t - prev_triangles;   /* 1‑based index inside block */
    idx_t j = offset_in_group;                    /* ascending j in the block   */
    idx_t k = S - j;                              /* corresponding k           */

    /* 4. Compute p,q,r and the sides a,b,c.  All calculations stay in
       seq_t, avoiding overflow for the ranges of interest (n up to 10k
       gives j,k ≈ 80 and c < 1e5).                                 */
    seq_t sj = (seq_t)j;
    seq_t sk = (seq_t)k;

    seq_t jj = sj * sj;                           /* j^2          */
    seq_t p = (seq_t)2 * jj;                      /* 2*j^2        */
    seq_t two_k_minus_one = (seq_t)2 * sk - 1;     /* 2*k-1        */
    seq_t q = two_k_minus_one * two_k_minus_one;   /* (2k-1)^2     */
    seq_t r = (seq_t)2 * sj * two_k_minus_one;     /* 2*j*(2k-1)   */

    seq_t a_val = q + r;
    seq_t b_val = p + r;
    seq_t c_val = p + q + r;

    /* 5. Return the correct side according to the position of n within
       the current triangle.  Indexing is 0‑based: 0→a, 1→b, 2→c.   */
    idx_t pos = (n - 1) % 3;
    if (pos == 0) return a_val;
    if (pos == 1) return b_val;
    return c_val;
}
